window.NGU_PHAP_TAB["/lessons/hsk3-bai-18.html"] = [{"so":"1","ten":"Cấu trúc 「只要……，就……」","tenVn":"","cauTruc":["只要 + [điều kiện]，(Chủ ngữ 2) + 就 + [kết quả]"],"giaiThich":"\"只要……，就……\" kết nối một câu phức chỉ điều kiện, \"只要\" theo sau là điều kiện cần thiết, \"就\" theo sau là kết quả tương ứng. Chủ ngữ có thể đặt trước hoặc sau 只要. Nếu có chủ ngữ thứ hai thì phải đặt trước 就.","viDu":[{"zh":"只要我有时间，就一定跟你去旅游。","py":"Zhǐyào wǒ yǒu shíjiān, jiù yídìng gēn nǐ qù lǚyóu.","vn":"Chỉ cần tôi có thời gian, nhất định sẽ đi du lịch cùng bạn."},{"zh":"我只要喜欢，就一定会买。","py":"Wǒ zhǐyào xǐhuan, jiù yídìng huì mǎi.","vn":"Chỉ cần tôi thích, nhất định sẽ mua."},{"zh":"只要你想去，我就跟你去。","py":"Zhǐyào nǐ xiǎng qù, wǒ jiù gēn nǐ qù.","vn":"Chỉ cần bạn muốn đi, tôi sẽ đi cùng bạn."},{"zh":"只要你给我买，我就能照顾好它。","py":"Zhǐyào nǐ gěi wǒ mǎi, wǒ jiù néng zhàogù hǎo tā.","vn":"Chỉ cần bạn mua cho tôi, tôi sẽ chăm nó tốt."}],"loi":[{"sai":"只要你努力，成功你就会。","why":"đảo trật tự vế sau; 就 đứng trước động từ.","dung":"只要你努力，你就会成功。"},{"sai":"只要你努力，才会成功。","why":"只要 đi với 就, không đi với 才.","dung":"只要你努力，就会成功。"},{"sai":"只要明天不下雨，就我们去爬山。","why":"chủ ngữ vế sau đứng TRƯỚC 就.","dung":"只要明天不下雨，我们就去爬山。"}],"bt":[{"so":1,"tieuDe":"Chọn / điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["只要你努力，","。"],"dap":[["就会成功"]],"chon":["就会成功","才会成功","会成功就"],"goiY":"“Chỉ cần bạn cố gắng là sẽ thành công.”","giai":"只要 đi cặp với 就."},{"kieu":"dien","phan":["只要明天不下雨，","。"],"dap":[["我们就去爬山"]],"chon":["我们就去爬山","就我们去爬山","我们去爬山就"],"goiY":"“Chỉ cần mai không mưa là chúng tôi đi leo núi.”","giai":"Chủ ngữ thứ hai đứng trước 就."},{"kieu":"dien","phan":["只要有时间，我","。"],"dap":[["就看书"]],"chon":["就看书","才看书","看书就"],"goiY":"“Chỉ cần có thời gian là tôi đọc sách.”","giai":"就 trước động từ."},{"kieu":"dien","phan":["","。"],"dap":[["只有努力，才能成功"]],"chon":["只有努力，才能成功","只有努力，就能成功","只要努力，才能成功"],"goiY":"Điều kiện DUY NHẤT thì dùng 只有……才…….","giai":"只有 đi với 才; 只要 đi với 就."},{"kieu":"dien","phan":["你","。"],"dap":[["只要多练习，就会进步"]],"chon":["只要多练习，就会进步","只要多练习，进步就会","只要多练习，才会进步"],"goiY":"Chủ ngữ có thể đứng TRƯỚC 只要.","giai":"只要 + điều kiện，就 + kết quả."},{"kieu":"dien","phan":["只要你说一声，我","。"],"dap":[["就来"]],"chon":["就来","才来","来就"],"goiY":"“Chỉ cần bạn gọi một tiếng là tôi đến ngay.”","giai":"只要……就…… nhấn mạnh điều kiện dễ đạt."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["只要","你","努力","就","会","成功"],"dap":["只要你努力，就会成功。"],"goiY":"Chỉ cần bạn cố gắng là sẽ thành công.","giai":"只要……就……."},{"kieu":"xep","manh":["只要","明天","不","下雨","我们","就","去","爬山"],"dap":["只要明天不下雨，我们就去爬山。"],"goiY":"Chỉ cần mai không mưa là chúng tôi đi leo núi.","giai":"Chủ ngữ 2 + 就."},{"kieu":"xep","manh":["只要","你","说","一声","我","就","来"],"dap":["只要你说一声，我就来。"],"goiY":"Chỉ cần bạn gọi một tiếng là tôi đến ngay.","giai":"只要……我就……."},{"kieu":"dungsai","cau":"只要你努力，就会成功。","dung":true,"giai":"只要 đi cặp với 就 — đúng."},{"kieu":"dungsai","cau":"只要你努力，才会成功。","dung":false,"sua":"只要你努力，就会成功。","giai":"只要 không đi với 才."},{"kieu":"dungsai","cau":"只要明天不下雨，就我们去爬山。","dung":false,"sua":"只要明天不下雨，我们就去爬山。","giai":"Chủ ngữ vế sau trước 就."}]},{"so":3,"tieuDe":"Dịch Việt – Trung","cap":"Giao tiếp","cau":[{"kieu":"dich","vn":"Chỉ cần bạn cố gắng là sẽ thành công.","dap":["只要你努力，就会成功。"],"py":"Zhǐyào nǐ nǔlì, jiù huì chénggōng.","goiY":"Dịch sang tiếng Trung, dùng 只要……就…….","giai":"只要……就……."},{"kieu":"dich","vn":"Chỉ cần có thời gian là tôi đọc sách.","dap":["只要有时间，我就看书。"],"py":"Zhǐyào yǒu shíjiān, wǒ jiù kàn shū.","goiY":"Dịch sang tiếng Trung, dùng 只要……就…….","giai":"只要 + điều kiện，我就 + động từ."}]}]},{"so":"2","ten":"Giới từ 「关于」","tenVn":"","cauTruc":["关于 + [danh từ/chủ đề]，[nội dung]"],"giaiThich":"\"关于\" theo sau là một danh từ, dùng để dẫn ra đối tượng được đề cập đến trong câu.","viDu":[{"zh":"我最近看了一些关于中国文化的电影。","py":"Wǒ zuìjìn kànle yìxiē guānyú Zhōngguó wénhuà de diànyǐng.","vn":"Gần đây tôi xem một số phim về văn hóa Trung Quốc."},{"zh":"关于这件事，我们还没有决定呢。","py":"Guānyú zhè jiàn shì, wǒmen hái méiyǒu juédìng ne.","vn":"Về việc này, chúng tôi vẫn chưa quyết định."},{"zh":"关于出国学习的事，妈妈已经同意了。","py":"Guānyú chūguó xuéxí de shì, māma yǐjīng tóngyì le.","vn":"Về việc đi du học nước ngoài, mẹ đã đồng ý rồi."},{"zh":"关于这个工作，还有什么问题吗？","py":"Guānyú zhège gōngzuò, hái yǒu shénme wèntí ma?","vn":"Về công việc này, còn vấn đề gì không?"}],"loi":[{"sai":"关于这个问题，我们讨论关于。","why":"关于 chỉ dùng MỘT lần, ở đầu cụm chủ đề.","dung":"关于这个问题，我们讨论一下。"},{"sai":"我们讨论关于这个问题。","why":"cụm 关于 thường đứng ĐẦU câu làm chủ đề, không đứng sau động từ.","dung":"关于这个问题，我们讨论一下。"},{"sai":"关于他，我很了解他关于。","why":"lặp 关于 và lặp tân ngữ.","dung":"关于他，我很了解。"}],"bt":[{"so":1,"tieuDe":"Chọn / điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["","，我们讨论一下。"],"dap":[["关于这个问题"]],"chon":["关于这个问题","这个问题关于","关于讨论这个问题"],"goiY":"“Về vấn đề này, chúng ta thảo luận một chút.”","giai":"Cụm 关于 + danh từ đứng đầu câu, nêu chủ đề."},{"kieu":"dien","phan":["","，我什么都不知道。"],"dap":[["关于那件事"]],"chon":["关于那件事","那件事关于","关于知道那件事"],"goiY":"“Về chuyện đó, tôi không biết gì cả.”","giai":"关于 + cụm danh từ."},{"kieu":"dien","phan":["这是一本","。"],"dap":[["关于中国文化的书"]],"chon":["关于中国文化的书","关于中国文化书","书关于中国文化的"],"goiY":"关于 cũng làm định ngữ, cần thêm 的.","giai":"关于…… + 的 + danh từ."},{"kieu":"dien","phan":["","，老师说了很多。"],"dap":[["关于学汉语"]],"chon":["关于学汉语","学汉语关于","关于说了学汉语"],"goiY":"“Về việc học tiếng Trung, thầy đã nói rất nhiều.”","giai":"关于 + cụm động từ làm chủ đề cũng được."},{"kieu":"dien","phan":["我很喜欢这部","。"],"dap":[["关于北京的电影"]],"chon":["关于北京的电影","关于北京电影","电影关于北京的"],"goiY":"“Tôi rất thích bộ phim về Bắc Kinh này.”","giai":"关于 + N + 的 + N."},{"kieu":"dien","phan":["","，我很了解。"],"dap":[["关于他"]],"chon":["关于他","他关于","关于了解他"],"goiY":"“Về cậu ấy, tôi hiểu rất rõ.”","giai":"关于 + đại từ, đứng đầu câu."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["关于","这个","问题","我们","讨论","一下"],"dap":["关于这个问题，我们讨论一下。"],"goiY":"Về vấn đề này, chúng ta thảo luận một chút.","giai":"关于 + N，chủ ngữ + động từ."},{"kieu":"xep","manh":["这","是","一","本","关于","中国","文化","的","书"],"dap":["这是一本关于中国文化的书。"],"goiY":"Đây là một quyển sách về văn hóa Trung Quốc.","giai":"关于…… + 的 + 书."},{"kieu":"xep","manh":["关于","那","件","事","我","什么","都","不","知道"],"dap":["关于那件事，我什么都不知道。"],"goiY":"Về chuyện đó, tôi chẳng biết gì cả.","giai":"关于 + N ở đầu câu."},{"kieu":"dungsai","cau":"关于这个问题，我们讨论一下。","dung":true,"giai":"关于 + N ở đầu câu — đúng."},{"kieu":"dungsai","cau":"这是一本关于中国文化的书。","dung":true,"giai":"关于…… + 的 + danh từ — đúng."},{"kieu":"dungsai","cau":"关于他，我很了解他关于。","dung":false,"sua":"关于他，我很了解。","giai":"关于 chỉ dùng một lần; không lặp tân ngữ."}]},{"so":3,"tieuDe":"Dịch Việt – Trung","cap":"Giao tiếp","cau":[{"kieu":"dich","vn":"Về vấn đề này, chúng ta thảo luận một chút.","dap":["关于这个问题，我们讨论一下。"],"py":"Guānyú zhège wèntí, wǒmen tǎolùn yíxià.","goiY":"Dịch sang tiếng Trung, dùng 关于.","giai":"关于 + N ở đầu câu."},{"kieu":"dich","vn":"Đây là một quyển sách về văn hóa Trung Quốc.","dap":["这是一本关于中国文化的书。"],"py":"Zhè shì yì běn guānyú Zhōngguó wénhuà de shū.","goiY":"Dịch sang tiếng Trung, dùng 关于 làm định ngữ.","giai":"关于…… + 的 + danh từ."}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk3-bai-19.html"] = [{"so":"1","ten":"Nghĩa mở rộng của bổ ngữ chỉ phương hướng","tenVn":"","cauTruc":["V + 出来 (tạo mới/nhận ra) | Adj/V + 下来 (chuyển tĩnh) | V + 起来 (nhớ lại) | 看 + 起来/上去 (đánh giá)"],"giaiThich":"Bổ ngữ chỉ phương hướng đặt sau động từ/tính từ còn có thể mang nghĩa mở rộng: 动词+出来 diễn tả từ KHÔNG đến CÓ (tạo ra sự vật mới) hoặc PHÂN BIỆT, NHẬN RA; 形容词/动词+下来 diễn tả sự chuyển từ động sang tĩnh, mạnh sang yếu, nhanh sang chậm; 动词+起来 diễn tả sự HỒI TƯỞNG, NHỚ LẠI có kết quả. Riêng 看起来/看上去 lại diễn tả sự ĐÁNH GIÁ, ƯỚC LƯỢNG qua quan sát, không mang nghĩa hồi tưởng.","viDu":[{"zh":"你没看出来吗？他是小刚啊。","py":"Nǐ méi kàn chulai ma? Tā shì Xiǎogāng a.","vn":"Bạn không nhận ra à? Đó là Tiểu Cương đấy."},{"zh":"只要他爸爸学小鸟叫，她马上就安静下来了。","py":"Zhǐyào tā bàba xué xiǎo niǎo jiào, tā mǎshàng jiù ānjìng xialai le.","vn":"Chỉ cần bố nó bắt chước tiếng chim con kêu là con bé lập tức yên lặng ngay."},{"zh":"我也想起来了。她现在慢慢地开始像个女孩子了。","py":"Wǒ yě xiǎng qilai le. Tā xiànzài mànman de kāishǐ xiàng ge nǚháizi le.","vn":"Anh cũng nhớ ra rồi. Bây giờ con dần dần bắt đầu giống con gái thật rồi."},{"zh":"他今天穿蓝西服，看上去像40多岁。","py":"Tā jīntiān chuān lán xīfú, kàn shangqu xiàng sìshí duō suì.","vn":"Hôm nay anh ấy mặc âu phục xanh, trông như hơn 40 tuổi."}],"loi":[{"sai":"我想出来了他的名字。","why":"“nhớ ra” dùng 想起来, không dùng 想出来.","dung":"我想起来他的名字了。"},{"sai":"看出来他很累。","why":"“trông có vẻ” là 看起来/看上去, không phải 看出来.","dung":"看起来他很累。"},{"sai":"天气冷起来了。","why":"chuyển từ mạnh sang yếu, động sang tĩnh thì dùng 下来.","dung":"天气冷下来了。"}],"bt":[{"so":1,"tieuDe":"Chọn / điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我","他的名字了。"],"dap":[["想起来"]],"chon":["想起来","想出来","想下来"],"goiY":"“Tôi nhớ ra tên cậu ấy rồi.” (hồi tưởng)","giai":"V + 起来 = nhớ lại, hồi tưởng có kết quả."},{"kieu":"dien","phan":["他","很累。"],"dap":[["看起来"]],"chon":["看起来","看出来","看下来"],"goiY":"“Cậu ấy trông có vẻ rất mệt.” (đánh giá qua quan sát)","giai":"看起来/看上去 = trông có vẻ, ước lượng."},{"kieu":"dien","phan":["我","是谁在说话。"],"dap":[["听出来"]],"chon":["听出来","听起来","听下来"],"goiY":"“Tôi nhận ra ai đang nói.” (phân biệt, nhận ra)","giai":"V + 出来 = phân biệt, nhận ra."},{"kieu":"dien","phan":["天气","了。"],"dap":[["冷下来"]],"chon":["冷下来","冷起来","冷出来"],"goiY":"“Trời đã dịu lại rồi.” (mạnh → yếu)","giai":"Adj + 下来 = chuyển từ mạnh sang yếu, động sang tĩnh."},{"kieu":"dien","phan":["他","一首歌。"],"dap":[["写出来"]],"chon":["写出来","写起来","写下来"],"goiY":"“Cậu ấy viết ra một bài hát.” (từ không thành có)","giai":"V + 出来 = tạo ra sự vật mới."},{"kieu":"dien","phan":["教室里","了。"],"dap":[["安静下来"]],"chon":["安静下来","安静起来","安静出来"],"goiY":"“Lớp học yên lặng dần.” (động → tĩnh)","giai":"安静下来 = lặng dần."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","想","起来","他","的","名字","了"],"dap":["我想起来他的名字了。"],"goiY":"Tôi nhớ ra tên cậu ấy rồi.","giai":"想起来 = nhớ ra."},{"kieu":"xep","manh":["我","听","出来","是","谁","在","说话"],"dap":["我听出来是谁在说话。"],"goiY":"Tôi nhận ra ai đang nói.","giai":"听出来 = nhận ra."},{"kieu":"xep","manh":["教室","里","安静","下来","了"],"dap":["教室里安静下来了。"],"goiY":"Trong lớp đã yên lặng dần rồi.","giai":"安静下来 = động → tĩnh."},{"kieu":"dungsai","cau":"我想出来了他的名字。","dung":false,"sua":"我想起来他的名字了。","giai":"“Nhớ ra” dùng 想起来."},{"kieu":"dungsai","cau":"看起来他很累。","dung":true,"giai":"看起来 = trông có vẻ — đúng."},{"kieu":"dungsai","cau":"天气冷起来了。","dung":false,"sua":"天气冷下来了。","giai":"Mạnh → yếu dùng 下来."}]},{"so":3,"tieuDe":"Dịch Việt – Trung","cap":"Giao tiếp","cau":[{"kieu":"dich","vn":"Tôi nhớ ra tên cậu ấy rồi.","dap":["我想起来他的名字了。"],"py":"Wǒ xiǎng qǐlái tā de míngzi le.","goiY":"Dịch sang tiếng Trung, chọn đúng bổ ngữ phương hướng mở rộng.","giai":"想起来 = hồi tưởng."},{"kieu":"dich","vn":"Cậu ấy trông có vẻ rất vui.","dap":["他看起来很高兴。"],"py":"Tā kàn qǐlái hěn gāoxìng.","goiY":"Dịch sang tiếng Trung, chọn đúng bổ ngữ phương hướng mở rộng.","giai":"看起来 = trông có vẻ."}]}]},{"so":"2","ten":"「使」「叫」「让」","tenVn":"","cauTruc":["[Nguyên nhân] + 使/叫/让 + [Đối tượng] + [Kết quả]"],"giaiThich":"\"使\" \"叫\" \"让\" khi kết hợp với thành phần kiêm ngữ (chỉ đối tượng nào đó) đứng sau, đều dùng để diễn tả ý nghĩa khiến cho. Ba từ này về cơ bản có nghĩa giống nhau, \"使\" thường dùng trong văn viết, \"叫\" thường dùng trong văn nói.","viDu":[{"zh":"读书使我快乐。","py":"Dúshū shǐ wǒ kuàilè.","vn":"Đọc sách khiến tôi vui vẻ."},{"zh":"考试让我很紧张。","py":"Kǎoshì ràng wǒ hěn jǐnzhāng.","vn":"Thi cử khiến tôi rất căng thẳng."},{"zh":"穿运动服让他更年轻。","py":"Chuān yùndòngfú ràng tā gèng niánqīng.","vn":"Mặc đồ thể thao khiến anh ấy trẻ hơn."},{"zh":"我想快点儿把照片发给大家，叫朋友们也高兴高兴。","py":"Wǒ xiǎng kuài diǎnr bǎ zhàopiàn fā gěi dàjiā, jiào péngyoumen yě gāoxìng gāoxìng.","vn":"Tôi muốn gửi ảnh cho mọi người sớm, để bạn bè cũng vui vẻ một chút."}],"loi":[{"sai":"这件事我很高兴。","why":"thiếu 使/让 để nối nguyên nhân với kết quả.","dung":"这件事使我很高兴。"},{"sai":"这个消息让高兴我。","why":"đối tượng phải đứng ngay sau 让.","dung":"这个消息让我很高兴。"},{"sai":"老师使我们做作业。","why":"使 chỉ nêu kết quả tâm lý/trạng thái, không dùng để SAI ai làm gì.","dung":"老师让我们做作业。"}],"bt":[{"so":1,"tieuDe":"Chọn / điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["这件事","。"],"dap":[["使我很高兴"]],"chon":["使我很高兴","我很高兴","使很高兴我"],"goiY":"“Chuyện này làm tôi rất vui.”","giai":"Nguyên nhân + 使 + đối tượng + kết quả."},{"kieu":"dien","phan":["这个消息","。"],"dap":[["让大家很吃惊"]],"chon":["让大家很吃惊","让很吃惊大家","大家让很吃惊"],"goiY":"“Tin đó khiến mọi người rất ngạc nhiên.”","giai":"让 + đối tượng + kết quả."},{"kieu":"dien","phan":["老师","我们做作业。"],"dap":[["让"]],"chon":["让","使","被"],"goiY":"Sai ai làm việc gì thì dùng 让/叫, không dùng 使.","giai":"使 chỉ nêu kết quả tâm lý/trạng thái."},{"kieu":"dien","phan":["妈妈","。"],"dap":[["叫我早点儿回家"]],"chon":["叫我早点儿回家","叫早点儿回家我","我叫早点儿回家"],"goiY":"“Mẹ bảo tôi về nhà sớm.”","giai":"叫 + người + việc, thường dùng trong văn nói."},{"kieu":"dien","phan":["这本书","。"],"dap":[["使我明白了很多道理"]],"chon":["使我明白了很多道理","使明白了我很多道理","我使明白了很多道理"],"goiY":"使 thường dùng trong VĂN VIẾT.","giai":"使 + đối tượng + kết quả, sắc thái văn viết."},{"kieu":"dien","phan":["妈妈","。"],"dap":[["不让我看电视"]],"chon":["不让我看电视","让我不看电视吗","让不我看电视"],"goiY":"Phủ định đứng TRƯỚC 让.","giai":"不 đứng trước 让."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["这","件","事","使","我","很","高兴"],"dap":["这件事使我很高兴。"],"goiY":"Chuyện này làm tôi rất vui.","giai":"Nguyên nhân + 使 + tôi + kết quả."},{"kieu":"xep","manh":["妈妈","叫","我","早点儿","回","家"],"dap":["妈妈叫我早点儿回家。"],"goiY":"Mẹ bảo tôi về nhà sớm.","giai":"叫 + người + việc."},{"kieu":"xep","manh":["妈妈","不","让","我","看","电视"],"dap":["妈妈不让我看电视。"],"goiY":"Mẹ không cho tôi xem TV.","giai":"不 trước 让."},{"kieu":"dungsai","cau":"这件事使我很高兴。","dung":true,"giai":"使 + đối tượng + kết quả — đúng."},{"kieu":"dungsai","cau":"这个消息让高兴我。","dung":false,"sua":"这个消息让我很高兴。","giai":"Đối tượng đứng ngay sau 让."},{"kieu":"dungsai","cau":"老师使我们做作业。","dung":false,"sua":"老师让我们做作业。","giai":"Sai ai làm gì thì dùng 让/叫."}]},{"so":3,"tieuDe":"Dịch Việt – Trung","cap":"Giao tiếp","cau":[{"kieu":"dich","vn":"Chuyện này làm tôi rất vui.","dap":["这件事使我很高兴。"],"py":"Zhè jiàn shì shǐ wǒ hěn gāoxìng.","goiY":"Dịch sang tiếng Trung, dùng 使/让.","giai":"使 + đối tượng + kết quả."},{"kieu":"dich","vn":"Mẹ không cho tôi xem TV.","dap":["妈妈不让我看电视。"],"py":"Māma bú ràng wǒ kàn diànshì.","goiY":"Dịch sang tiếng Trung, dùng 让.","giai":"不 đứng trước 让."}]}]}];
window.NGU_PHAP_TAB["/lessons/hsk3-bai-20.html"] = [{"so":"1","ten":"Câu có từ 「被」","tenVn":"","cauTruc":["Chủ ngữ + 被/叫/让 + (Tân ngữ) + Động từ + Thành phần khác"],"giaiThich":"Có thể dùng câu mang từ \"被\" để diễn tả nghĩa bị động, cấu trúc câu là \"chủ ngữ + 被/叫/让 + tân ngữ + động từ + các thành phần khác\", trong đó chủ ngữ là đối tượng chịu tác động của hành động còn tân ngữ là chủ thể của hành động. Có thể lược bỏ tân ngữ đứng sau từ 被, nhưng không được lược bỏ tân ngữ đứng sau 叫 hay 让. Lưu ý: phó từ phủ định và động từ năng nguyện phải đặt TRƯỚC từ 被.","viDu":[{"zh":"我被他影响的。","py":"Wǒ bèi tā yǐngxiǎng de.","vn":"Mình bị anh ấy ảnh hưởng đấy."},{"zh":"问题还没有被解决呢。","py":"Wèntí hái méiyǒu bèi jiějué ne.","vn":"Vấn đề vẫn chưa được giải quyết."},{"zh":"我们经常被别人认错。","py":"Wǒmen jīngcháng bèi biéren rèncuò.","vn":"Chúng tôi thường bị người khác nhận nhầm."},{"zh":"多么难的问题，都会被解决的。","py":"Duōme nán de wèntí, dōu huì bèi jiějué de.","vn":"Vấn đề dù khó đến mấy cũng sẽ được giải quyết."}],"loi":[{"sai":"我的手机被他没拿走。","why":"phủ định phải đứng TRƯỚC 被.","dung":"我的手机没被他拿走。"},{"sai":"我的手机被拿。","why":"sau động từ trong câu 被 phải có thành phần khác (了/bổ ngữ).","dung":"我的手机被拿走了。"},{"sai":"杯子叫打破了。","why":"sau 叫/让 KHÔNG được lược tân ngữ (chỉ 被 mới lược được).","dung":"杯子被打破了。／杯子叫弟弟打破了。"}],"bt":[{"so":1,"tieuDe":"Chọn / điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我的手机","。"],"dap":[["被他拿走了"]],"chon":["被他拿走了","被他拿","他被拿走了"],"goiY":"“Điện thoại của tôi bị cậu ấy lấy đi rồi.”","giai":"Chủ ngữ + 被 + tác nhân + V + thành phần khác."},{"kieu":"dien","phan":["杯子","。"],"dap":[["被打破了"]],"chon":["被打破了","叫打破了","被打"],"goiY":"Sau 被 có thể LƯỢC tân ngữ.","giai":"Chỉ 被 mới lược được tân ngữ, 叫/让 thì không."},{"kieu":"dien","phan":["我的手机","。"],"dap":[["没被他拿走"]],"chon":["没被他拿走","被他没拿走","被没他拿走"],"goiY":"Phủ định: “Điện thoại của tôi không bị lấy đi.”","giai":"没 đứng TRƯỚC 被."},{"kieu":"dien","phan":["杯子","。"],"dap":[["叫弟弟打破了"]],"chon":["叫弟弟打破了","叫打破了弟弟","弟弟叫打破了"],"goiY":"“Cái cốc bị em trai làm vỡ rồi.” (dùng 叫)","giai":"叫 + tác nhân (không được lược) + V + 了."},{"kieu":"dien","phan":["这件事","。"],"dap":[["不会被人知道"]],"chon":["不会被人知道","被人不会知道","被不会人知道"],"goiY":"Động từ năng nguyện đứng TRƯỚC 被.","giai":"不会 đứng trước 被."},{"kieu":"dien","phan":["那篇文章","。"],"dap":[["被老师改好了"]],"chon":["被老师改好了","被老师改","老师被改好了"],"goiY":"“Bài văn đó đã được thầy sửa xong rồi.”","giai":"改好了 = bổ ngữ kết quả + 了."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["我","的","手机","被","他","拿","走","了"],"dap":["我的手机被他拿走了。"],"goiY":"Điện thoại của tôi bị cậu ấy lấy đi rồi.","giai":"被 + tác nhân + V + bổ ngữ + 了."},{"kieu":"xep","manh":["杯子","叫","弟弟","打","破","了"],"dap":["杯子叫弟弟打破了。"],"goiY":"Cái cốc bị em trai làm vỡ rồi.","giai":"叫 + tác nhân bắt buộc."},{"kieu":"xep","manh":["那","篇","文章","被","老师","改","好","了"],"dap":["那篇文章被老师改好了。"],"goiY":"Bài văn đó đã được thầy sửa xong rồi.","giai":"改好了 = bổ ngữ kết quả."},{"kieu":"dungsai","cau":"我的手机被他拿走了。","dung":true,"giai":"被 + tác nhân + V + 了 — đúng."},{"kieu":"dungsai","cau":"我的手机被他没拿走。","dung":false,"sua":"我的手机没被他拿走。","giai":"没 đứng trước 被."},{"kieu":"dungsai","cau":"杯子叫打破了。","dung":false,"sua":"杯子被打破了。","giai":"Sau 叫 không được lược tân ngữ."}]},{"so":3,"tieuDe":"Dịch Việt – Trung","cap":"Giao tiếp","cau":[{"kieu":"dich","vn":"Điện thoại của tôi bị cậu ấy lấy đi rồi.","dap":["我的手机被他拿走了。"],"py":"Wǒ de shǒujī bèi tā ná zǒu le.","goiY":"Dịch sang tiếng Trung, dùng câu chữ 被.","giai":"被 + tác nhân + V + 走了."},{"kieu":"dich","vn":"Cái cốc không bị làm vỡ.","dap":["杯子没被打破。"],"py":"Bēizi méi bèi dǎ pò.","goiY":"Dịch sang tiếng Trung, dùng câu chữ 被 ở dạng phủ định.","giai":"没 đứng trước 被."}]}]},{"so":"2","ten":"Cấu trúc 「只有……，才……」","tenVn":"","cauTruc":["只有 + [điều kiện duy nhất]，才 + [kết quả]"],"giaiThich":"\"只有……，才……\" kết nối một câu phức chỉ điều kiện, phần đứng sau 只有 diễn tả điều kiện DUY NHẤT, phần đứng sau 才 diễn tả kết quả chỉ xuất hiện trong điều kiện này.","viDu":[{"zh":"只有写完作业，才能看电视。","py":"Zhǐyǒu xiěwán zuòyè, cái néng kàn diànshì.","vn":"Chỉ có làm xong bài tập mới được xem tivi."},{"zh":"看来只有爱，才能让人有变化。","py":"Kànlái zhǐyǒu ài, cái néng ràng rén yǒu biànhuà.","vn":"Xem ra chỉ có tình yêu mới có thể khiến người ta thay đổi."},{"zh":"只有你们的爸爸妈妈才能分出来哪个是哥哥，哪个是弟弟吧。","py":"Zhǐyǒu nǐmen de bàba māma cái néng fēn chulai nǎge shì gēge, nǎge shì dìdi ba.","vn":"Chỉ có bố mẹ các bạn mới phân biệt được ai là anh, ai là em nhỉ."},{"zh":"所以只有真正做事情的时候，才能了解有多难。","py":"Suǒyǐ zhǐyǒu zhēnzhèng zuò shìqing de shíhou, cái néng liǎojiě yǒu duō nán.","vn":"Vì vậy chỉ khi thực sự bắt tay vào làm mới hiểu được nó khó đến đâu."}],"loi":[{"sai":"只有努力，就能成功。","why":"只有 đi cặp với 才, không đi với 就.","dung":"只有努力，才能成功。"},{"sai":"只有努力，能成功才。","why":"才 đứng TRƯỚC động từ.","dung":"只有努力，才能成功。"},{"sai":"只有你去，才我也去。","why":"chủ ngữ vế sau đứng TRƯỚC 才.","dung":"只有你去，我才去。"}],"bt":[{"so":1,"tieuDe":"Chọn / điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["只有努力，","。"],"dap":[["才能成功"]],"chon":["才能成功","就能成功","能成功才"],"goiY":"“Chỉ có cố gắng mới thành công được.”","giai":"只有 đi cặp với 才."},{"kieu":"dien","phan":["只有你去，","。"],"dap":[["我才去"]],"chon":["我才去","才我去","我去才"],"goiY":"“Chỉ khi bạn đi thì tôi mới đi.”","giai":"Chủ ngữ vế sau đứng trước 才."},{"kieu":"dien","phan":["","。"],"dap":[["只要有时间，我就去"]],"chon":["只要有时间，我就去","只有有时间，我就去","只要有时间，我才去"],"goiY":"Điều kiện DỄ đạt thì dùng 只要……就…….","giai":"只要→就 (dễ); 只有→才 (duy nhất)."},{"kieu":"dien","phan":["只有多练习，","。"],"dap":[["才能说得好"]],"chon":["才能说得好","就能说得好","能说得好才"],"goiY":"“Chỉ khi luyện nhiều mới nói giỏi được.”","giai":"才 + động từ năng nguyện + động từ."},{"kieu":"dien","phan":["只有老师同意，","。"],"dap":[["我们才能去"]],"chon":["我们才能去","才我们能去","我们能去才"],"goiY":"“Chỉ khi thầy đồng ý chúng tôi mới được đi.”","giai":"Chủ ngữ 2 + 才 + 能 + động từ."},{"kieu":"dien","phan":["只有这个办法，","。"],"dap":[["才能解决问题"]],"chon":["才能解决问题","就能解决问题","解决问题才能"],"goiY":"“Chỉ có cách này mới giải quyết được vấn đề.”","giai":"只有 + N，才……."}]},{"so":2,"cap":"Bán giao tiếp","tieuDe":"Sắp xếp câu · Câu đúng hay sai","cau":[{"kieu":"xep","manh":["只有","努力","才","能","成功"],"dap":["只有努力，才能成功。"],"goiY":"Chỉ có cố gắng mới thành công được.","giai":"只有……才能……."},{"kieu":"xep","manh":["只有","你","去","我","才","去"],"dap":["只有你去，我才去。"],"goiY":"Chỉ khi bạn đi thì tôi mới đi.","giai":"Chủ ngữ 2 + 才."},{"kieu":"xep","manh":["只有","多","练习","才","能","说","得","好"],"dap":["只有多练习，才能说得好。"],"goiY":"Chỉ khi luyện nhiều mới nói giỏi được.","giai":"只有……才能……."},{"kieu":"dungsai","cau":"只有努力，才能成功。","dung":true,"giai":"只有……才…… — đúng."},{"kieu":"dungsai","cau":"只有努力，就能成功。","dung":false,"sua":"只有努力，才能成功。","giai":"只有 không đi với 就."},{"kieu":"dungsai","cau":"只有你去，才我去。","dung":false,"sua":"只有你去，我才去。","giai":"Chủ ngữ vế sau trước 才."}]},{"so":3,"tieuDe":"Dịch Việt – Trung","cap":"Giao tiếp","cau":[{"kieu":"dich","vn":"Chỉ có cố gắng mới thành công được.","dap":["只有努力，才能成功。"],"py":"Zhǐyǒu nǔlì, cái néng chénggōng.","goiY":"Dịch sang tiếng Trung, dùng 只有……才…….","giai":"只有……才能……."},{"kieu":"dich","vn":"Chỉ khi bạn đi thì tôi mới đi.","dap":["只有你去，我才去。"],"py":"Zhǐyǒu nǐ qù, wǒ cái qù.","goiY":"Dịch sang tiếng Trung, dùng 只有……才…….","giai":"Chủ ngữ vế sau trước 才."}]}]}];
